typedef float rational_t;
typedef unsigned int size_t;

inline void *operator new(size_t, void *place) { return place; }

class stringx
{
  int reserved;
  void *rep;

public:
  stringx();
  stringx(const stringx &value) : reserved(0), rep(0) { *this = value; }
  ~stringx();
  stringx &operator=(const stringx &value);
};

template<class T>
class my_allocator
{
};

template<class T, class Allocator = my_allocator<T> >
class vector
{
  T *start;
  T *finish;
  T *end_of_storage;

  void _M_insert_aux(T *position, const T &value);

public:
  typedef T *iterator;

  iterator begin() { return start; }
  iterator end() { return finish; }

  void push_back(const T &value)
  {
    if (finish != end_of_storage)
    {
      new (finish) T(value);
      ++finish;
    }
    else
      _M_insert_aux(end(), value);
  }

  iterator erase(iterator position)
  {
    if (position + 1 != end())
      for (iterator source = position + 1; source != end(); ++source, ++position)
        *position = *source;
    --finish;
    finish->~T();
    return position;
  }
};

class timer_widget
{
protected:
  class timer_func
  {
  public:
    rational_t time;
    stringx function;

    timer_func(const timer_func &value)
      : time(value.time), function(value.function)
    {
    }

    timer_func &operator=(const timer_func &value)
    {
      time = value.time;
      function = value.function;
      return *this;
    }
  };

  char padding[0x18c];
  rational_t time_left;
  bool running, updated;
  char alignment[2];
  vector<timer_func> script_calls_left;
  vector<timer_func> script_calls_made;

public:
  void set_time_left(rational_t _time_left);
};

void timer_widget::set_time_left( rational_t _time_left )
{
  if(_time_left > time_left)
  {
    vector<timer_func>::iterator sci = script_calls_made.begin();
    while(sci != script_calls_made.end())
    {
      if(_time_left > (*sci).time)
      {
        script_calls_left.push_back((*sci));
        sci = script_calls_made.erase(sci);
      }
      else
        ++sci;
    }
  }
  else if(_time_left < time_left)
  {
    vector<timer_func>::iterator sci = script_calls_left.begin();
    while(sci != script_calls_left.end())
    {
      if(_time_left <= (*sci).time)
      {
        script_calls_made.push_back((*sci));
        sci = script_calls_left.erase(sci);
      }
      else
        ++sci;
    }
  }

  time_left = _time_left;
  if ( time_left < 0.0f )
    time_left = 0.0f;
  updated = false;
}
